head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vPopUpYn = '';
scwin.vPopDel = '';
scwin.vIsurCd, scwin.vBasIsuNm, scwin.vIsurNm;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.arrPar = new Array();
scwin.processGp; // 등록 1, 수정 4, 삭제 5
scwin.vBtnStat_S, scwin.vBtnStat_M, scwin.vBtnStat_D;
scwin.btnStat = new Object();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 호출파라미터설정
        scwin.setParam();

        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(pnl_IsurSearch);
        $c.bns.BnsPanelToGroupBox(pnl_Input);

        // 발행기관 검색 포커스
        if (scwin.vPopUpYn === '') txb_IsurCd.setValue("");
        txb_IsurCd.focus();
        scwin.vIsurCd = txb_IsurCd.getValue();

        // 가우스헤더 셋팅(입력항목)
        const sbmOptions = {
            id : "sbm_dts_SaveItem",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_SaveItem=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20800.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_IsurCd_onkeypress
 * @description txb_IsurCd onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurCd_onkeypress = function() {
    try {
        if (scwin.vPopUpYn !== '') return;
        if (event.keyCode === 13) scwin.searchIsur();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20800.txb_IsurCd_onkeypress" });
    }
};

/**
 * @method
 * @name img_IsurCdNm_onclick
 * @description img_IsurCdNm 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsurCdNm_onclick = function() {
    try {
        if (scwin.vPopUpYn !== '') return;
        scwin.showIsur(lbl_IsurNmCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20800.img_IsurCdNm_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        if (scwin.vPopUpYn !== '') {
            if (scwin.btnStat.Search = "dis") return;
            return;
        }
        scwin.searchIsur();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20800.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_IsurList_OnLoadError
 * @description dts_IsurList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IsurList_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20800.dts_IsurList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IsurList_OnLoadCompleted
 * @description dts_IsurList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IsurList_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
        if (scwin.vPopUpYn !== '') {
            dts_IsurList.setRowPosition(1, 0);
            scwin.vIsurCd = dts_IsurList.getCellData(dts_IsurList.getRowPosition(), "ISUR_CD");
            scwin.list();
        } else {
            dts_IsurList.setRowPosition(0, 0);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20800.dts_IsurList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_IsurList_OnClick
 * @description grd_IsurList 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.grd_IsurList_OnClick = function(row) {
    try {
        scwin.vIsurCd = dts_IsurList.getCellData(dts_IsurList.getRowPosition(), "ISUR_CD");
        scwin.list();
        scwin.clearTextField();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20800.grd_IsurList_OnClick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20800.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        dts_List.setRowPosition(0, 0);
        $c.bns.CloseWinArrPnlRight(rowcount, pnl_Input, grd_List);
        scwin.btnSetChange(1);
        if (scwin.vPopUpYn === 'Y') {
            const vRow = $c.cp.getNameValueRow(dts_List, "BAS_ISU_NM", scwin.arrPar[0].BAS_ISU_NM);
            dts_List.setRowPosition(vRow, 0);
            if (scwin.vPopDel !== 'Y') {
                txb_BasIsuNm.setValue(scwin.arrPar[0].BAS_ISU_NM);
                txb_BasIsuAbbrv.setValue(scwin.arrPar[0].BAS_ISU_ABBRV);
                txb_BasIsuEngNm.setValue(scwin.arrPar[0].BAS_ISU_ENG_NM);
                txb_BasIsuEngAbbrv.setValue(scwin.arrPar[0].BAS_ISU_ENG_ABBRV);
            } else {
                txb_BasIsuNm.setValue("");
                txb_BasIsuAbbrv.setValue("");
                txb_BasIsuEngNm.setValue("");
                txb_BasIsuEngAbbrv.setValue("");
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20800.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    try {
        if (dts_List.getRowCount() !== 0) {
            scwin.btnSetChange(2);
            txb_BasIsuNm.setValue(dts_List.getCellData(row, "BAS_ISU_NM"));
            txb_BasIsuAbbrv.setValue(dts_List.getCellData(row, "BAS_ISU_ABBRV"));
            txb_BasIsuEngNm.setValue(dts_List.getCellData(row, "BAS_ISU_ENG_NM"));
            txb_BasIsuEngAbbrv.setValue(dts_List.getCellData(row, "BAS_ISU_ENG_ABBRV"));
        } else {
            scwin.clearTextField();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20800.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name btn_Reset_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Reset_onclick = function() {
    try {
        if (scwin.vPopUpYn !== '') {
            if (scwin.btnStat.Reset = "dis") return;
            return;
        }
        scwin.clearTextField();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20800.btn_Reset_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        scwin.processGp = '1';
        if (scwin.btnStat.Save === "dis") return;
        await scwin.insertModDel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20800.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Mod_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Mod_onclick = async function() {
    try {
        scwin.processGp = '4';
        if (scwin.btnStat.Mod === "dis") return;
        await scwin.insertModDel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20800.btn_Mod_onclick" });
    }
};

/**
 * @method
 * @name btn_Del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Del_onclick = async function() {
    try {
        scwin.processGp = '5';
        if (scwin.btnStat.Del === "dis") return;
        await scwin.insertModDel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20800.btn_Del_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.processGp === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
            scwin.clearTextField();
        }
        if (scwin.processGp === '4') {
            if (scwin.vPopUpYn === '') {
                await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
                scwin.clearTextField();
            } else if (scwin.vPopUpYn !== '') {
                // 부모 창 전송 값 설정
                scwin.arrPar[0].MOD_YN = 'Y';
                scwin.fn_SetPar(scwin.arrPar);
            }
        }
        if (scwin.processGp === '5') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
            scwin.clearTextField();
            scwin.vPopDel = 'Y'; // 필드 클리어하기 위한키
            if (scwin.vPopUpYn !== '') {
                // 부모 창 전송 값 설정
                scwin.arrPar[0].DEL_YN = 'Y';
                scwin.fn_SetPar(scwin.arrPar);
            }
        }
        dts_List.Reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20800.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        if (scwin.processGp === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
        }
        if (scwin.processGp === '4') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        }
        if (scwin.processGp === '5') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20800.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_Cfm_onclick
 * @description 「주권종목명확인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Cfm_onclick = function() {
    try {
        if (scwin.vIsurCd === "") return;
        scwin.fn_GetPar = scwin.getStkIsuNm;
        $c.bns.fn_PopStkIsuSearch(lbl_IsurNmCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20800.btn_Cfm_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20800.btn_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchIsur
 * @description 발행기관 리스트를 조회 한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchIsur = function() {
    let dsNm = 'BNS_ISUR_INFO';
    let qryId = 'lds.stf.bnscommon.select.listIsurCd';
    let param = '';
    if (scwin.vPopUpYn === '') {
        param = '&{P}V_ISUR_NM=' + txb_IsurCd.getValue();
    } else {
        param = '&{P}V_ISUR_NM=' + scwin.vIsurCd;
    }
    $c.bns.fn_SearchBns('ULDBNS20800.xml', dts_IsurList, dsNm, qryId, param);
};

/**
 * @method
 * @name showIsur
 * @description 발행기관 팝업을 보여준다.
 * @param {String} txb_IsurCd txb_IsurCd
 * @returns {void}
 * @hidden N
 */
scwin.showIsur = function(txb_IsurCd) {
    scwin.fn_GetPar = scwin.getParIsurCd;
    scwin.fn_SetPar = scwin.setParIsurCd;
    $c.bns.fn_PopIsurSearch(txb_IsurCd);
};

/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: txb_IsurCd.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_IsurCd.setValue(scwin.arrPar[0].ISUR_NM);
};

/**
 * @method
 * @name list
 * @description 채권기준명 리스트를 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.list = function() {
    let dsNm = 'BNS_ISU_BAS_NM';
    let qryId = 'lds.stf.bnscommon.select.listIsuBasNm';
    let param = '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    param += '&{P}V_POP_YN=' + 'N';
    $c.bns.fn_SearchBns('ULDBNS20800.xml', dts_List, dsNm, qryId, param);
    $c.bns.ShowWinArrPnlRight(pnl_Input, grd_List);
};

/**
 * @method
 * @name btnSetChange
 * @description 버튼 셋(저장,수정,삭제) 변경
 * @param {*} num num
 * @returns {void}
 * @hidden N
 */
scwin.btnSetChange = function(num) {
    if (num === 1) {
        btn_Save.setBackgroundImage("../img/bns/btn_40.gif");
        btn_Mod.setBackgroundImage("../img/bns/btn_modify_nd.gif");
        btn_Del.setBackgroundImage("../img/bns/btn_delete_nd.gif");
        scwin.btnStat.Search = "en";
        scwin.btnStat.Reset = "en";
        scwin.btnStat.Save = "en";
        scwin.btnStat.Mod = "dis";
        scwin.btnStat.Del = "dis";
    } else if (num === 2) {
        btn_Save.setBackgroundImage("../img/bns/btn_40_d.gif");
        btn_Mod.setBackgroundImage("../img/bns/btn_modify_n.gif");
        btn_Del.setBackgroundImage("../img/bns/btn_delete_n.gif");
        scwin.btnStat.Search = "en";
        scwin.btnStat.Reset = "en";
        scwin.btnStat.Save = "dis";
        scwin.btnStat.Mod = "en";
        scwin.btnStat.Del = "en";
    }
    if (scwin.vPopUpYn !== '') {
        btn_Search.setBackgroundImage("../img/bns/btn_select_nd.gif");
        btn_Reset.setBackgroundImage("../img/bns/btn_new_nd.gif");
        btn_Save.setBackgroundImage("../img/bns/btn_40_d.gif");
        btn_Mod.setBackgroundImage("../img/bns/btn_modify_n.gif");
        btn_Del.setBackgroundImage("../img/bns/btn_delete_n.gif");
        scwin.btnStat.Search = "dis";
        scwin.btnStat.Reset = "dis";
        scwin.btnStat.Save = "dis";
        scwin.btnStat.Mod = "en";
        scwin.btnStat.Del = "en";
    }
};

/**
 * @method
 * @name clearTextField
 * @description 텍스트 필드를 초기화 한다.
 * @returns {void}
 * @hidden N
 */
scwin.clearTextField = function() {
    txb_BasIsuNm.setValue('');
    txb_BasIsuAbbrv.setValue('');
    txb_BasIsuEngNm.setValue('');
    txb_BasIsuEngAbbrv.setValue('');
    dts_List.Reset();
    scwin.btnSetChange(1);
};

/**
 * @method
 * @name getStkIsuNm
 * @description 주권종목명 팝업에 넘길 키데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getStkIsuNm = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: scwin.vIsurCd,
        POP_CALL_YN: 'Y'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name inputCheck
 * @description 필수 입력값 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function() {
    // 등록, 수정, 삭제 시 체크
    if (scwin.vBasIsuNm === '') {
        await $c.win.alert("[한글기준명]을 입력하십시오.");
        txb_BasIsuNm.focus();
        return false;
    }

    // 자리수 체크
    if (!$c.stf.checkMaxLength(txb_BasIsuNm, 60, '한글기준명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuAbbrv, 20, '한글기준약명')) return false;
    const pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    let str = txb_BasIsuEngNm.getValue();
    for (let i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            await $c.win.alert('영문기준명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngNm.focus();
            return false;
        }
    }
    let str = txb_BasIsuEngAbbrv.getValue();
    for (let i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            await $c.win.alert('영문기준약명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }

    // 등록, 수정 시 체크
    if (scwin.processGp === '1' || scwin.processGp === '4') {
        if (txb_BasIsuAbbrv.getValue() === '') {
            await $c.win.alert("[한글기준약명]을 입력하십시오.");
            txb_BasIsuAbbrv.focus();
            return false;
        }
        if (txb_BasIsuEngNm.getValue() === '') {
            await $c.win.alert("[영문기준명]을 입력하십시오.");
            txb_BasIsuEngNm.focus();
            return false;
        }
        if (txb_BasIsuEngAbbrv.getValue() === '') {
            await $c.win.alert("[영문기준약명]을 입력하십시오.");
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }

    // 수정, 삭제 시 체크
    if (scwin.processGp === '4' || scwin.processGp === '5') {
        let processGpNm;
        if (scwin.processGp === '4') processGpNm = '수정';
        if (scwin.processGp === '5') processGpNm = '삭제';
        // 기준종목명 동일 여부 체크
        if (scwin.vBasIsuNm !== dts_List.getCellData(dts_List.getRowPosition(), "BAS_ISU_NM")) {
            await $c.win.alert("한글기준명은 수정하실수 없습니다.");
            txb_BasIsuNm.setValue(dts_List.getCellData(dts_List.getRowPosition(), "BAS_ISU_NM"));
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name duplCheck
 * @description 등록 시, 중복 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.duplCheck = async function() {
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (txb_BasIsuNm.getValue() === dts_List.getCellData(i, "BAS_ISU_NM")) {
            await $c.win.alert("동일한 [한글기준명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuNm.focus();
            return false;
        }
        if (txb_BasIsuAbbrv.getValue() === dts_List.getCellData(i, "BAS_ISU_ABBRV")) {
            await $c.win.alert("동일한 [한글기준약명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuAbbrv.focus();
            return false;
        }
        if (txb_BasIsuEngNm.getValue() === dts_List.getCellData(i, "BAS_ISU_ENG_NM")) {
            await $c.win.alert("동일한 [영문기준명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuEngNm.focus();
            return false;
        }
        if (txb_BasIsuEngAbbrv.getValue() === dts_List.getCellData(i, "BAS_ISU_ENG_ABBRV")) {
            await $c.win.alert("동일한 [영문기준약명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name setDataSet
 * @description 텍스트 필드를 데이터셋에 설정
 * @returns {void}
 * @hidden N
 */
scwin.setDataSet = function() {
    dts_SaveItem.insertRow();
    dts_SaveItem.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_SaveItem.setCellData(1, "BAS_ISU_NM", txb_BasIsuNm.getValue());
    dts_SaveItem.setCellData(1, "BAS_ISU_ABBRV", txb_BasIsuAbbrv.getValue());
    dts_SaveItem.setCellData(1, "BAS_ISU_ENG_NM", txb_BasIsuEngNm.getValue());
    dts_SaveItem.setCellData(1, "BAS_ISU_ENG_ABBRV", txb_BasIsuEngAbbrv.getValue());
};

/**
 * @method
 * @name insertModDel
 * @description 등록 및 수정, 삭제를 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insertModDel = async function() {
    scwin.vBasIsuNm = txb_BasIsuNm.getValue();
    // 필수입력값 체크
    if (await scwin.inputCheck() === false) return;
    let url;
    if (scwin.processGp === '1') {
        // 중복체크
        if (await scwin.duplCheck() === false) return;
        if (!confirm("한글기준명 " + scwin.vBasIsuNm + "으로 등록하시겠습니까?")) return;
        url = "/bns/ListBzAppl.do?method=createIsuBas";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    } else if (scwin.processGp === '4') {
        let output = "한글기준명 " + scwin.vBasIsuNm + "를 수정시겠습니까?";
        output += "\n" + "수정된 한글기준명은 수정일 이후부터 적용되니,";
        output += "\n" + "기 상장종목의 한글기준명 변경 시 별도로 조치하여야 합니다.";
        if (!confirm(output)) return;
        url = "/bns/ListBzAppl.do?method=updateIsuBas";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    } else if (scwin.processGp === '5') {
        if (!confirm("한글기준명 " + scwin.vBasIsuNm + "를 삭제하시겠습니까?")) return;
        url = "/bns/ListBzAppl.do?method=deleteIsuBas";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    }
    url += "&SCREN_ID=" + 'ULDBNS20800.xml';
    url += "&ISUR_CD=" + scwin.vIsurCd;

    // if (dts_SaveItem.NameValue(1, "BAS_ISU_NM") != dts_List.NameValue(1, "BAS_ISU_NM")) {
    scwin.setDataSet();
    // }
    dts_SaveItem.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaveItem)";
    trs_Save.Post();
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.vPopUpYn = scwin.arrPar[0].POP_CALL;
        scwin.vIsurCd = scwin.arrPar[0].ISUR_CD;
        txb_IsurCd.setValue(scwin.arrPar[0].ISUR_NM);
        scwin.searchIsur();
    }
};
